INSERT INTO audit_events VALUES(9098,'2026-08-24 18:39:46','12e1fa55-72b','builder','/home/iconbaypark2900/openworker-workspace/opensciencelab','','replace_in_file','proposed','','','{"new": "def test_dft_non_converged_returns_none(monkeypatch):\\n    \"\"\"A non-converged SCF (mf.converged False) is NEVER returned as a\\n    real number.  We patch the PySCF RKS factory so that ``mf.kernel()``\\n    leaves ``mf.converged = False``, and the adapter''s no-raise contract\\n    turns that into ``None`` (the stamped-surrogate path) -- the MO\\n    energies from a non-converged run are not a real number and must\\n    never surface to the caller.\"\"\"\\n    import opensciencelab.dft as d\\n    from o...", "old": "def test_dft_non_converged_returns_none(monkeypatch):\\n    \"\"\"A non-converged SCF (mf.converged False) is NEVER returned as a\\n    real number.  We monkeypatch the kernel to force non-convergence,\\n    and the adapter returns None (the stamped-surrogate path), not a gap.\\n    \"\"\"\\n    import opensciencelab.dft as d\\n    from opensciencelab.base import Candidate\\n    if not d.pyscf_available():\\n        import pytest\\n        pytest.skip(\"PySCF not available on this box\")\\n    import numpy as ...", "path": "opensciencelab/tests.py"}','','','');
